// Plain-language insights generated by code from detected patterns (translatable templates, never the LLM).
import type { Forecast } from './forecast';

export type Insight =
  | { code: 'monthly_income'; day: number; amount_cents: number; count: number; source: string }
  | { code: 'recurring_weekly'; weekday: number; amount_cents: number; count: number; source: string }
  | { code: 'piece_jobs'; per_week: number; amount_cents: number; count: number }
  | { code: 'tight_day'; day: number }
  | { code: 'busy_weekday'; weekday: number; amount_cents: number }
  | { code: 'shortfall_gap'; amount_cents: number; date: string };

export function buildInsights(f: Forecast, max = 3): Insight[] {
  const out: Insight[] = [];
  const { recurring, pieceJobs, spending } = f.patterns;

  // When money may run short, lead with the one number that fixes it.
  if (f.shortfall) {
    const worst = Math.min(...f.days.map((d) => d.balance_cents));
    out.push({ code: 'shortfall_gap', amount_cents: -worst, date: f.shortfall.date });
  }

  for (const p of recurring) {
    if (p.kind === 'monthly') out.push({ code: 'monthly_income', day: p.day!, amount_cents: p.amount_cents, count: p.occurrences, source: p.source });
    else out.push({ code: 'recurring_weekly', weekday: p.weekday!, amount_cents: p.amount_cents, count: p.occurrences, source: p.source });
  }
  if (pieceJobs) out.push({ code: 'piece_jobs', per_week: pieceJobs.per_week, amount_cents: pieceJobs.median_cents, count: pieceJobs.occurrences });
  if (spending.tight_day) out.push({ code: 'tight_day', day: spending.tight_day });
  if (spending.busiest_weekday != null) out.push({ code: 'busy_weekday', weekday: spending.busiest_weekday, amount_cents: spending.by_weekday[spending.busiest_weekday] });
  return out.slice(0, max);
}
